import {
  Group,
  Mesh,
  TorusKnotGeometry,
  CylinderGeometry,
  TorusGeometry,
  CircleGeometry,
  PlaneGeometry,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
  DirectionalLight,
  HemisphereLight,
  Color,
  RepeatWrapping,
  DoubleSide,
} from 'three/webgpu';
import {
  texture,
  uv,
  vec2,
  vec3,
  color,
  float,
  mix,
  smoothstep,
  oneMinus,
  length,
  positionLocal,
  normalLocal,
  mx_noise_float,
} from 'three/tsl';
import gsap from 'gsap';
import { createMSDFText } from '@/text';

// Nova Atelier — "Pedestal material study" node.
// Procedural cinematic-floor pedestal + torus-knot material study (mesh render mode).
// No GLB is available for this node; the knot / pedestal / chamfer / contact-shadow /
// backdrop are all built from primitive geometries + TSL node materials.

function resolveText(list, role, fallback) {
  if (!Array.isArray(list)) return fallback;
  const match = list.find((item) => item?.role === role || item?.type === role);
  if (!match) return fallback;
  return match.value ?? match.text ?? fallback;
}

export default function createNode(config, ctx) {
  const scenePos = config?.scenePosition ?? {};

  const group = new Group();
  group.name = 'pedestal-material-study';
  group.userData.nodeId = config?.id ?? 'pedestal-material-study';
  group.userData.handlers = {};

  group.position.set(scenePos.x ?? 0, scenePos.y ?? 0, scenePos.z ?? 0);
  if (Array.isArray(scenePos.rotationXYZ)) {
    group.rotation.set(
      scenePos.rotationXYZ[0] ?? 0,
      scenePos.rotationXYZ[1] ?? 0,
      scenePos.rotationXYZ[2] ?? 0
    );
  }
  const targetScale = Array.isArray(scenePos.scaleXYZ) ? scenePos.scaleXYZ : [1, 1, 1];

  // ---------------------------------------------------------------------
  // Roughness map (brushed-metal grain). Loader returns a cached texture
  // synchronously; three.js resolves the pixel data internally once ready.
  // ---------------------------------------------------------------------
  const roughnessMapUrl =
    config?.assets?.imageUrl ?? '/prism-assets/chrome/brushed-metal.map.png';
  const roughnessMap = ctx.textureLoader.load(roughnessMapUrl);
  roughnessMap.wrapS = RepeatWrapping;
  roughnessMap.wrapT = RepeatWrapping;

  // ---------------------------------------------------------------------
  // Torus knot — the material study subject.
  // ---------------------------------------------------------------------
  const knotGeometry = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMaterial = new MeshPhysicalNodeMaterial();
  knotMaterial.color = new Color('#c9cdd4');
  knotMaterial.metalness = 0.55;
  knotMaterial.clearcoat = 0.22;
  knotMaterial.clearcoatRoughness = 0.35;
  knotMaterial.anisotropy = 0.9;
  knotMaterial.anisotropyRotation = Math.PI / 2; // rotated 90deg to the tube direction

  // Roughness map MULTIPLIES the base value, so it is normalized against its
  // ~0.9 center before being scaled by the target 0.55 base roughness — this
  // keeps the material swap-proof if the map's average brightness shifts.
  const mapRoughness = texture(roughnessMap).r;
  const roughnessCenter = float(0.9);
  const baseRoughness = float(0.55);
  const roughnessJitter = mx_noise_float(uv().mul(180.0)).mul(0.02); // 2% value jitter
  knotMaterial.roughnessNode = mapRoughness
    .div(roughnessCenter)
    .mul(baseRoughness)
    .add(roughnessJitter)
    .clamp(0.05, 1.0);

  // Procedural scratch-noise normal perturbation (strength 0.15), elongated
  // along the anisotropy/tube direction to read as brushed streaks.
  const scratchUV = uv().mul(vec2(650.0, 5.0));
  const scratchNoise = mx_noise_float(scratchUV).sub(0.5).mul(0.15);
  knotMaterial.normalNode = normalLocal
    .add(vec3(scratchNoise, scratchNoise.mul(0.6), 0.0))
    .normalize();

  const knotMesh = new Mesh(knotGeometry, knotMaterial);
  knotMesh.position.set(0, 0.4, 0);
  knotMesh.castShadow = true;
  knotMesh.receiveShadow = true;

  // Pivot sits exactly on the Y axis with the knot centered above it — the
  // knot's local origin has zero XZ offset, so rotating the pivot about Y
  // produces the "knot rotates about y" self-spin the spec calls for.
  const knotPivot = new Group();
  knotPivot.name = 'knot-pivot';
  knotPivot.add(knotMesh);
  group.add(knotPivot);

  // ---------------------------------------------------------------------
  // Pedestal (top face at y = -0.35, height 0.5).
  // ---------------------------------------------------------------------
  const pedestalGeometry = new CylinderGeometry(1.1, 1.1, 0.5, 64);
  const pedestalMaterial = new MeshPhysicalNodeMaterial();
  pedestalMaterial.color = new Color('#14141a');
  pedestalMaterial.roughness = 0.7;
  pedestalMaterial.metalness = 0.35;
  const pedestalMesh = new Mesh(pedestalGeometry, pedestalMaterial);
  pedestalMesh.position.set(0, -0.6, 0);
  pedestalMesh.receiveShadow = true;
  group.add(pedestalMesh);

  // Chamfered top edge (0.03-unit chamfer, approximated as a slim ring
  // catching the key light right at the pedestal's top rim).
  const chamferGeometry = new TorusGeometry(1.085, 0.015, 12, 96);
  const chamferMaterial = new MeshPhysicalNodeMaterial();
  chamferMaterial.color = new Color('#1c1c22');
  chamferMaterial.roughness = 0.4;
  chamferMaterial.metalness = 0.5;
  const chamferMesh = new Mesh(chamferGeometry, chamferMaterial);
  chamferMesh.rotation.x = Math.PI / 2;
  chamferMesh.position.set(0, -0.35, 0);
  group.add(chamferMesh);

  // ---------------------------------------------------------------------
  // Contact shadow — radial gradient disc, center opacity 0.6 falling to 0
  // over the outer 0.4 units of a 1.5-unit-radius disc. Held a hair above
  // the pedestal top face (rather than exactly coincident) so it renders
  // instead of being swallowed by the pedestal's solid top cap.
  // ---------------------------------------------------------------------
  const shadowGeometry = new CircleGeometry(1.5, 64);
  const shadowMaterial = new MeshBasicNodeMaterial();
  shadowMaterial.transparent = true;
  shadowMaterial.depthWrite = false;
  shadowMaterial.side = DoubleSide;
  const distFromCenter = length(positionLocal.xy);
  const shadowFalloff = oneMinus(smoothstep(1.1, 1.5, distFromCenter));
  shadowMaterial.colorNode = color('#000000');
  shadowMaterial.opacityNode = shadowFalloff.mul(0.6);
  const shadowMesh = new Mesh(shadowGeometry, shadowMaterial);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -0.348, 0);
  shadowMesh.renderOrder = 2;
  group.add(shadowMesh);

  // ---------------------------------------------------------------------
  // Backdrop — 7x6 plane at z = -3 with the vertical engineered gradient.
  // ---------------------------------------------------------------------
  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  const stop0 = color('#0b0b10');
  const stop1 = color('#101017');
  const stop2 = color('#16161d');
  const gradientT = uv().y;
  const gradientLower = mix(stop0, stop1, smoothstep(0.0, 0.7, gradientT));
  backdropMaterial.colorNode = mix(gradientLower, stop2, smoothstep(0.7, 1.0, gradientT));
  const backdropMesh = new Mesh(backdropGeometry, backdropMaterial);
  backdropMesh.position.set(0, 0, -3);
  group.add(backdropMesh);

  // ---------------------------------------------------------------------
  // Neutral studio lighting substitute for the PMREM IBL (intensity 0.7)
  // — a hemisphere fill plus a directional key/fill pair so the brushed
  // anisotropy streaks actually catch highlights.
  // ---------------------------------------------------------------------
  const hemiLight = new HemisphereLight('#e8ecf2', '#0b0b10', 0.7);
  group.add(hemiLight);

  const keyLight = new DirectionalLight('#ffffff', 1.3);
  keyLight.position.set(2.2, 3.0, 2.6);
  group.add(keyLight);

  const fillLight = new DirectionalLight('#c9cdd4', 0.35);
  fillLight.position.set(-2.4, 1.2, -1.5);
  group.add(fillLight);

  // ---------------------------------------------------------------------
  // Text — MSDF only, on the 0.25-unit rhythm.
  // ---------------------------------------------------------------------
  const headlineText = resolveText(config?.textContent, 'headline', 'Material study 03');
  const captionText = resolveText(
    config?.textContent,
    'caption',
    'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT'
  );

  const headlineMesh = createMSDFText(ctx.fontAtlas, {
    text: headlineText,
    fontFamily: 'Lora',
    fontWeight: 600,
    size: 0.34,
    color: '#e8ecf2',
    letterSpacing: -0.005,
    lineHeight: 1.1,
    anchorX: 'center',
    anchorY: 'middle',
  });
  headlineMesh.position.set(0, -1.2, 0.02);
  group.add(headlineMesh);

  const captionMesh = createMSDFText(ctx.fontAtlas, {
    text: captionText,
    fontFamily: 'JetBrains Mono',
    fontWeight: 400,
    size: 0.09,
    color: '#e8ecf2',
    letterSpacing: 0.08,
    lineHeight: 1.4,
    anchorX: 'center',
    anchorY: 'middle',
  });
  captionMesh.position.set(0, -1.6, 0.02);
  group.add(captionMesh);

  // ---------------------------------------------------------------------
  // Cinematic primitives — applied via the shared library only, never
  // inlined. "orbit" targets the knot pivot (the visual subject).
  // ---------------------------------------------------------------------
  const appliedPrimitiveHandles = [];
  (config?.cinematicPrimitives ?? []).forEach((primitive) => {
    const applyPrimitive = ctx.primitives?.[primitive.name];
    if (typeof applyPrimitive !== 'function') return;
    const target = primitive.name === 'orbit' ? knotPivot : group;
    const handle = applyPrimitive(target, primitive.params ?? {});
    appliedPrimitiveHandles.push(handle);
  });

  // ---------------------------------------------------------------------
  // Weighted-settle entrance (overshoot 1.04 -> 1.0, 0.9s).
  // ---------------------------------------------------------------------
  group.scale.set(0.001, 0.001, 0.001);
  const settleTimeline = gsap.timeline();
  settleTimeline
    .fromTo(
      group.scale,
      { x: 0.001, y: 0.001, z: 0.001 },
      {
        x: targetScale[0] * 1.04,
        y: targetScale[1] * 1.04,
        z: targetScale[2] * 1.04,
        duration: 0.55,
        ease: 'power2.out',
      }
    )
    .to(group.scale, {
      x: targetScale[0],
      y: targetScale[1],
      z: targetScale[2],
      duration: 0.35,
      ease: 'power4.out',
    });

  // ---------------------------------------------------------------------
  // Cleanup
  // ---------------------------------------------------------------------
  group.userData.cleanup = () => {
    settleTimeline.kill();

    appliedPrimitiveHandles.forEach((handle) => {
      if (!handle) return;
      if (typeof handle.stop === 'function') handle.stop();
      if (typeof handle.kill === 'function') handle.kill();
      if (typeof handle.dispose === 'function') handle.dispose();
    });

    roughnessMap.dispose();

    if (typeof headlineMesh?.userData?.cleanup === 'function') headlineMesh.userData.cleanup();
    if (typeof captionMesh?.userData?.cleanup === 'function') captionMesh.userData.cleanup();

    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        const materials = Array.isArray(child.material) ? child.material : [child.material];
        materials.forEach((mat) => {
          if (mat.map) mat.map.dispose?.();
          mat.dispose?.();
        });
      }
    });
  };

  return group;
}
